Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
net: rds: fix MR cleanup on copy error

__rds_rdma_map() hands sg/pages ownership to the transport after
get_mr() succeeds. If copying the generated cookie back to user space
fails after that point, the error path must not free those resources
again before dropping the MR reference.

Remove the duplicate unpin/free from the put_user() failure branch so
that MR teardown is handled only through the existing final cleanup
path.

Fixes: 0d4597c8c5ab ("net/rds: Track user mapped pages through special API")
Cc: stable@kernel.org
Reported-by: Yuan Tan <yuantan098@gmail.com>
Reported-by: Yifan Wu <yifanwucs@gmail.com>
Reported-by: Juefei Pu <tomapufckgml@gmail.com>
Reported-by: Xin Liu <bird@lzu.edu.cn>
Signed-off-by: Ao Zhou <draw51280@163.com>
Signed-off-by: Ren Wei <n05ec@lzu.edu.cn>
Reviewed-by: Allison Henderson <achender@kernel.org>
Link: https://patch.msgid.link/79c8ef73ec8e5844d71038983940cc2943099baf.1776764247.git.draw51280@163.com
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
After a successful `get_mr()` call, the transport takes ownership of the scatterlist (sg) and pages. The error path in `__rds_rdma_map()` when `put_user()` fails incorrectly attempted to free these resources again (`unpin_user_pages` and `kfree(sg)`), leading to a double-free or use-after-free bug. The fix removes that redundant cleanup, ensuring proper teardown occurs only through the transport's final cleanup path.

Here is the patch:

 static int __rds_rdma_map(struct rds_sock *rs, struct rds_get_mr_args *args,
 			  u64 *cookie_ret, struct rds_mr **mr_ret,
 			  struct rds_conn_path *cp)
 {
 	struct rds_mr *mr = NULL, *found;
 	struct scatterlist *sg = NULL;
 	unsigned int nr_pages;
 	struct page **pages = NULL;
 	void *trans_private;
 	unsigned long flags;
 	rds_rdma_cookie_t cookie;
 	unsigned int nents = 0;
 	int need_odp = 0;
 	long i;
 	int ret;

 	if (ipv6_addr_any(&rs->rs_bound_addr) || !rs->rs_transport) {
 		ret = -ENOTCONN; /* XXX not a great errno */
 		goto out;
 	}

 	if (!rs->rs_transport->get_mr) {
 		ret = -EOPNOTSUPP;
 		goto out;
 	}

 	/* If the combination of the addr and size requested for this memory
 	 * region causes an integer overflow, return error.
 	 */
 	if (((args->vec.addr + args->vec.bytes) < args->vec.addr) ||
 	    PAGE_ALIGN(args->vec.addr + args->vec.bytes) <
 		    (args->vec.addr + args->vec.bytes)) {
 		ret = -EINVAL;
 		goto out;
 	}

 	if (!can_do_mlock()) {
 		ret = -EPERM;
 		goto out;
 	}

 	nr_pages = rds_pages_in_vec(&args->vec);
 	if (nr_pages == 0) {
 		ret = -EINVAL;
 		goto out;
 	}

 	/* Restrict the size of mr irrespective of underlying transport
 	 * To account for unaligned mr regions, subtract one from nr_pages
 	 */
 	if ((nr_pages - 1) > (RDS_MAX_MSG_SIZE >> PAGE_SHIFT)) {
 		ret = -EMSGSIZE;
 		goto out;
 	}

 	rdsdebug("RDS: get_mr addr %llx len %llu nr_pages %u\n",
 		args->vec.addr, args->vec.bytes, nr_pages);

 	/* XXX clamp nr_pages to limit the size of this alloc? */
 	pages = kzalloc_objs(struct page *, nr_pages);
 	if (!pages) {
 		ret = -ENOMEM;
 		goto out;
 	}

 	mr = kzalloc_obj(struct rds_mr);
 	if (!mr) {
 		ret = -ENOMEM;
 		goto out;
 	}

 	kref_init(&mr->r_kref);
 	RB_CLEAR_NODE(&mr->r_rb_node);
 	mr->r_trans = rs->rs_transport;
 	mr->r_sock = rs;

 	if (args->flags & RDS_RDMA_USE_ONCE)
 		mr->r_use_once = 1;
 	if (args->flags & RDS_RDMA_INVALIDATE)
 		mr->r_invalidate = 1;
 	if (args->flags & RDS_RDMA_READWRITE)
 		mr->r_write = 1;

 	/*
 	 * Pin the pages that make up the user buffer and transfer the page
 	 * pointers to the mr's sg array.  We check to see if we've mapped
 	 * the whole region after transferring the partial page references
 	 * to the sg array so that we can have one page ref cleanup path.
 	 *
 	 * For now we have no flag that tells us whether the mapping is
 	 * r/o or r/w. We need to assume r/w, or we'll do a lot of RDMA to
 	 * the zero page.
 	 */
 	ret = rds_pin_pages(args->vec.addr, nr_pages, pages, 1);
 	if (ret == -EOPNOTSUPP) {
 		need_odp = 1;
 	} else if (ret <= 0) {
 		goto out;
 	} else {
 		nents = ret;
 		sg = kmalloc_objs(*sg, nents);
 		if (!sg) {
 			ret = -ENOMEM;
 			goto out;
 		}
 		WARN_ON(!nents);
 		sg_init_table(sg, nents);

 		/* Stick all pages into the scatterlist */
 		for (i = 0 ; i < nents; i++)
 			sg_set_page(&sg[i], pages[i], PAGE_SIZE, 0);

 		rdsdebug("RDS: trans_private nents is %u\n", nents);
 	}
 	/* Obtain a transport specific MR. If this succeeds, the
 	 * s/g list is now owned by the MR.
 	 * Note that dma_map() implies that pending writes are
 	 * flushed to RAM, so no dma_sync is needed here. */
 	trans_private = rs->rs_transport->get_mr(
 		sg, nents, rs, &mr->r_key, cp ? cp->cp_conn : NULL,
 		args->vec.addr, args->vec.bytes,
 		need_odp ? ODP_ZEROBASED : ODP_NOT_NEEDED);

 	if (IS_ERR(trans_private)) {
 		/* In ODP case, we don't GUP pages, so don't need
 		 * to release anything.
 		 */
 		if (!need_odp) {
 			unpin_user_pages(pages, nr_pages);
 			kfree(sg);
 		}
 		ret = PTR_ERR(trans_private);
 		/* Trigger connection so that its ready for the next retry */
 		if (ret == -ENODEV && cp)
 			rds_conn_connect_if_down(cp->cp_conn);
 		goto out;
 	}

 	mr->r_trans_private = trans_private;

 	rdsdebug("RDS: get_mr put_user key is %x cookie_addr %p\n",
 	       mr->r_key, (void *)(unsigned long) args->cookie_addr);

 	/* The user may pass us an unaligned address, but we can only
 	 * map page aligned regions. So we keep the offset, and build
 	 * a 64bit cookie containing <R_Key, offset> and pass that
 	 * around. */
 	if (need_odp)
 		cookie = rds_rdma_make_cookie(mr->r_key, 0);
 	else
 		cookie = rds_rdma_make_cookie(mr->r_key,
 					      args->vec.addr & ~PAGE_MASK);
 	if (cookie_ret)
 		*cookie_ret = cookie;

 	if (args->cookie_addr &&
 	    put_user(cookie, (u64 __user *)(unsigned long)args->cookie_addr)) {
-		if (!need_odp) {
-			unpin_user_pages(pages, nr_pages);
-			kfree(sg);
-		}
 		ret = -EFAULT;
 		goto out;
 	}

 	/* Inserting the new MR into the rbtree bumps its
 	 * reference count. */
 	spin_lock_irqsave(&rs->rs_rdma_lock, flags);
 	found = rds_mr_tree_walk(&rs->rs_rdma_keys, mr->r_key, mr);
 	spin_unlock_irqrestore(&rs->rs_rdma_lock, flags);

 	BUG_ON(found && found != mr);

 	rdsdebug("RDS: get_mr key is %x\n", mr->r_key);
 	if (mr_ret) {
 		kref_get(&mr->r_kref);
 		*mr_ret = mr;
 	}

 	ret = 0;
 out:
 	kfree(pages);
 	if (mr)
 		kref_put(&mr->r_kref, __rds_put_mr_final);
 	return ret;
 }



